// Embed the external browser asset for servers without filesystem access.
import { readFile, writeFile } from "node:fs/promises";
import { rolldown } from "rolldown";

const bundle = await rolldown({
  input: "src/runtime/resolve.ts",
  platform: "browser",
});
const { output } = await bundle.generate({
  format: "es",
  minify: true,
});
await bundle.close();

const js = output[0].code.trim();
const file = new URL("../src/runtime/resolve-source.ts", import.meta.url);
const source =
  "// Generated by scripts/build-resolver.ts\n" +
  "export const resolverSource = " +
  JSON.stringify(js) +
  ";\n";

if (process.argv.includes("--check")) {
  if ((await readFile(file, "utf8")) !== source) {
    throw new Error("Run pnpm run resolver:build.");
  }
} else {
  await writeFile(file, source);
}
